import sys
from collections import Counter

def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    # Convert input to integers
    A = [int(x) for x in input_data]

    # Count frequencies of each number
    counts = Counter(A)

    # Get the distinct numbers
    distinct_numbers = list(counts.keys())

    # Check if we can form a full house
    # We need two distinct numbers x and y such that count(x) >= 3 and count(y) >= 2
    possible = False
    n = len(distinct_numbers)
    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            if counts[distinct_numbers[i]] >= 3 and counts[distinct_numbers[j]] >= 2:
                possible = True
                break
        if possible:
            break

    if possible:
        print("Yes")
    else:
        print("No")

