class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        m = len(grid)
        n = len(grid[0])
        result = []

        # Iterate through each row to determine traversal order
        for r in range(m):
            # Determine the global index 'k' for each cell in the zigzag sequence.
            # For even rows (0, 2, ...), we traverse right (columns 0 to n-1).
            # For odd rows (1, 3, ...), we traverse left (columns n-1 to 0).
            # The global index 'k' is calculated based on the row and column position.
            # We keep the cell if 'k' is even (0, 2, 4, ...), as this corresponds to 
            # "Skip every alternate cell" starting from the first cell (0-based index 0).

            if r % 2 == 0:
                # Even rows: Traverse Right
                # The cells are at indices (r*n + 0), (r*n + 1), ..., (r*n + n-1)
                for c in range(n):
                    if (r * n + c) % 2 == 0:
                        result.append(grid[r][c])
            else:
                # Odd rows: Traverse Left
                # The cells are at indices (r*n + (n-1)), (r*n + (n-2)), ..., (r*n + 0)
                for c in range(n - 1, -1, -1):
                    if (r * n + (n - 1 - c)) % 2 == 0:
                        result.append(grid[r][c])

        return result

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        # dp[c1][c2] represents the minimum cost to paint the houses from 0 to i
        # such that house i has color c1 and house n-1-i has color c2.
        # Since we process pairs (i, n-1-i) for i from 0 to n/2 - 1,
        # we can maintain a DP table of size 3x3.

        # Initialize DP table for the first pair (i=0)
        # The cost is cost[0][c0] + cost[n-1][c1]
        # Constraint: c0 != c1
        dp = [[float('inf')] * 3 for _ in range(3)]

        for c0 in range(3):
            for c1 in range(3):
                if c0 != c1:
                    dp[c0][c1] = cost[0][c0] + cost[n-1][c1]
                else:
                    dp[c0][c1] = float('inf')

        # Iterate for i from 1 to n/2 - 1
        # We are transitioning from pair (i-1) to pair (i)
        # For pair (i), the houses are i and n-1-i
        # The colors are c_i and c'_{i} (where c'_{i} is the color of house n-1-i)
        # The constraints are:
        # 1. c_i != c_{i-1} (adjacent)
        # 2. c'_{i} != c'_{i-1} (adjacent)
        # 3. c_i != c'_{i} (symmetric)
        # Note: The cost for house i is cost[i][c_i] and for house n-1-i is cost[n-1-i][c'_{i}]

        for i in range(1, n // 2):
            new_dp = [[float('inf')] * 3 for _ in range(3)]
            for c_prev in range(3):
                for c_prev_prime in range(3):
                    # If the previous state was invalid, skip
                    if dp[c_prev][c_prev_prime] == float('inf'):
                        continue

                    for c_curr in range(3):
                        for c_curr_prime in range(3):
                            # Check constraints
                            # c_curr != c_prev (adjacent between i-1 and i)
                            # c_curr_prime != c_prev_prime (adjacent between n-1-i and n-1-(i-1))
                            # c_curr != c_curr_prime (symmetric between i and n-1-i)
                            if c_curr != c_prev and c_curr_prime != c_prev_prime and c_curr != c_curr_prime:
                                new_dp[c_curr][c_curr_prime] = min(new_dp[c_curr][c_curr_prime],
                                                                    dp[c_prev][c_prev_prime] + cost[i][c_curr] + cost[n-1-i][c_curr_prime])
            dp = new_dp

        # The final answer is the minimum cost for the last pair (n/2 - 1, n/2)
        # The last pair is (n/2 - 1, n/2). The symmetric constraint is c_{n/2-1} != c_{n/2}.
        # The DP state already includes the cost for house n/2 (since n-1-(n/2-1) = n/2).
        # And the constraints are satisfied.

        ans = float('inf')
        for c_last in range(3):
            for c_last_prime in range(3):
                if dp[c_last][c_last_prime] != float('inf'):
                    ans = min(ans, dp[c_last][c_last_prime])

        return ans

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        # Initialize the online status of all users to True
        online = [True] * numberOfUsers
        # Initialize the count of mentions for each user
        mentions = [0] * numberOfUsers
        # Dictionary to store the time when a user goes back online
        # Key: user_id, Value: timestamp when they come back online
        offline_until = {}

        # Sort events based on timestamp.
        # If timestamps are equal, OFFLINE events should be processed before MESSAGE events.
        # We assign a sort key: (0 if OFFLINE else 1, timestamp)
        # This ensures OFFLINE comes before MESSAGE at the same timestamp.
        sorted_events = sorted(events, key=lambda e: (0 if e[0] == 'OFFLINE' else 1, int(e[1])))

        for event in sorted_events:
            event_type = event[0]
            timestamp = int(event[1])
            details = event[2]

            if event_type == 'OFFLINE':
                # User goes offline
                user_id = int(details)
                # Mark user as offline and store the reactivation time
                offline_until[user_id] = timestamp + 60
            else:
                # MESSAGE Event

                # 1. Process Reactivation
                # Check all users to see if any have come back online before this timestamp.
                for u in range(numberOfUsers):
                    if u in offline_until and offline_until[u] <= timestamp:
                        online[u] = True

                # 2. Process Mentions
                if details == 'ALL':
                    # ALL mentions all users (online and offline)
                    for u in range(numberOfUsers):
                        mentions[u] += 1
                elif details == 'HERE':
                    # HERE mentions only online users
                    for u in range(numberOfUsers):
                        if online[u]:
                            mentions[u] += 1
                else:
                    # id<number> mentions specific users
                    # Split the string by whitespace
                    tokens = details.split()
                    for token in tokens:
                        # Parse user ID from token (format: id<number>)
                        if token.startswith('id'):
                            user_id = int(token[2:])
                            # Only count if user is online
                            if online[user_id]:
                                mentions[user_id] += 1

        return mentions

class Solution:
    def maxDifference(self, s: str) -> int:
        from collections import Counter

        # Count the frequency of each character in the string
        counts = Counter(s)

        max_odd_freq = 0
        min_even_freq = float('inf')

        # Iterate through the frequencies to find the maximum odd frequency 
        # and the minimum even frequency.
        for freq in counts.values():
            if freq % 2 == 1:
                # If frequency is odd, update the maximum odd frequency found so far
                if freq > max_odd_freq:
                    max_odd_freq = freq
            elif freq % 2 == 0:
                # If frequency is even, update the minimum even frequency found so far
                if freq < min_even_freq:
                    min_even_freq = freq

        # Return the difference between the maximum odd frequency and minimum even frequency
        return max_odd_freq - min_even_freq

class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        # Precompute divisors for numbers up to 100000.
        # Since the maximum value in groups and elements is 10^5, we can precompute the divisors for all numbers up to this limit.
        # This allows us to quickly iterate over divisors for each group.
        MAX_VAL = 100001
        divs = [[] for _ in range(MAX_VAL)]
        for i in range(1, MAX_VAL):
            for j in range(i, MAX_VAL, i):
                divs[j].append(i)

        # Create a map to store the smallest index for each element value in 'elements'.
        # This allows us to quickly find the index of an element if we know its value.
        min_index_map = {}
        for idx, val in enumerate(elements):
            if val not in min_index_map:
                min_index_map[val] = idx

        assigned = []

        # Iterate through each group and assign an element
        for g in groups:
            best_idx = -1
            # Iterate through all divisors of g
            # Since we need the element with the smallest index, we check all valid elements
            # that divide g and track the one with the smallest index found so far.
            for d in divs[g]:
                # Check if 'd' exists in our map of elements
                if d in min_index_map:
                    idx = min_index_map[d]
                    # We want the smallest index.
                    # Since we iterate through divisors, the order doesn't guarantee index order.
                    # So we check if this is the best index found so far.
                    if best_idx == -1 or idx < best_idx:
                        best_idx = idx
                        # Optimization: if we find an index 0, it's the smallest possible.
                        if best_idx == 0:
                            break
            assigned.append(best_idx)

        return assigned

class Solution:
    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        n = len(s)
        # Iterate through all possible starting positions for a substring of length k
        for i in range(n - k + 1):
            # Check if the substring s[i:i+k] consists of a single distinct character
            # We check if s[j] is equal to s[i] for all j in the substring
            is_uniform = True
            for j in range(i + 1, i + k):
                if s[j] != s[i]:
                    is_uniform = False
                    break

            # If the substring is not uniform, continue to the next position
            if not is_uniform:
                continue

            # Check boundary conditions
            # If there is a character immediately before the substring, it must be different
            if i > 0 and s[i-1] == s[i]:
                continue

            # If there is a character immediately after the substring, it must be different
            if i + k < n and s[i+k] == s[i]:
                continue

            # If all conditions are met, return True
            return True

        # If no such substring is found, return False
        return False

