class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        # Dictionary to store the count of each number across all subarrays of size k
        counts = {}
        n = len(nums)

        # Iterate through all possible subarrays of size k
        # A subarray starts at index i and ends at i + k - 1
        # The range of i goes from 0 to n - k
        for i in range(n - k + 1):
            # Iterate through the elements in the current subarray
            for j in range(i, i + k):
                num = nums[j]
                # Increment the count for this number
                counts[num] = counts.get(num, 0) + 1

        # Find the largest integer that appears in exactly one subarray
        result = -1
        for num, count in counts.items():
            if count == 1:
                if num > result:
                    result = num

        return result

class Solution:
    def maxContainers(self, n: int, w: int, maxWeight: int) -> int:
        # The deck has n * n cells.
        # Each container has a weight of w.
        # The ship has a maximum weight capacity of maxWeight.

        # The number of containers is limited by two factors:
        # 1. The physical space available on the deck (n * n).
        # 2. The weight capacity of the ship (maxWeight // w).

        # We return the minimum of these two limits.
        return min(n * n, maxWeight // w)

class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)

        # Build adjacency matrix for the graph
        adj = [[False] * n for _ in range(n)]

        # Calculate intersections for all pairs
        for i in range(n):
            for j in range(i + 1, n):
                # Convert lists to sets for efficient intersection
                set_i = set(properties[i])
                set_j = set(properties[j])
                intersection = len(set_i.intersection(set_j))

                # If intersection is at least k, add edge between nodes i and j
                if intersection >= k:
                    adj[i][j] = adj[j][i] = True

        # Count connected components using DFS
        visited = [False] * n
        components = 0

        for i in range(n):
            if not visited[i]:
                components += 1
                # Start DFS from node i
                stack = [i]
                visited[i] = True

                while stack:
                    node = stack.pop()
                    # Visit all neighbors
                    for neighbor in range(n):
                        if adj[node][neighbor] and not visited[neighbor]:
                            visited[neighbor] = True
                            stack.append(neighbor)

        return components

