class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        n = len(s)
        m = len(t)
        max_len = 0

        # Iterate over all substrings of s
        # i and j are start and end indices (inclusive of start, exclusive of end in slicing)
        # We iterate i from 0 to n, j from i to n+1 to cover all substrings including empty ones
        for i in range(n + 1):
            for j in range(i, n + 1):
                sub_s = s[i:j]

                # Iterate over all substrings of t
                for k in range(m + 1):
                    for l in range(k, m + 1):
                        sub_t = t[k:l]

                        # Concatenate and check if palindrome
                        combined = sub_s + sub_t
                        if combined == combined[::-1]:
                            max_len = max(max_len, len(combined))

        return max_len

