class Solution:
    def maxAdjacentDistance(self, nums: List[int]) -> int:
        n = len(nums)
        max_diff = 0
        # Iterate through each element to compare with its adjacent next element
        for i in range(n):
            # Calculate the absolute difference between the current element and the next element
            # (i + 1) % n handles the circular property (last element connects to first)
            diff = abs(nums[i] - nums[(i + 1) % n])
            if diff > max_diff:
                max_diff = diff
        return max_diff

class Solution:
    def findValidPair(self, s: str) -> str:
        # Count frequency of each digit in the string
        count = {}
        for char in s:
            digit = int(char)
            count[digit] = count.get(digit, 0) + 1

        # Iterate through adjacent pairs in the string
        for i in range(len(s) - 1):
            first_digit = int(s[i])
            second_digit = int(s[i+1])

            # Check if digits are different
            if first_digit != second_digit:
                # Check if first digit appears exactly first_digit times
                if count[first_digit] == first_digit:
                    # Check if second digit appears exactly second_digit times
                    if count[second_digit] == second_digit:
                        return s[i] + s[i+1]

        return ""

