class Solution:
    def sumOfGoodNumbers(self, nums: List[int], k: int) -> int:
        total_sum = 0
        n = len(nums)

        for i in range(n):
            is_good = True

            # Check if the element is strictly greater than the element at index i - k
            # If i - k exists (index >= 0), nums[i] must be strictly greater than nums[i - k]
            if i - k >= 0:
                if nums[i] <= nums[i - k]:
                    is_good = False

            # Check if the element is strictly greater than the element at index i + k
            # If i + k exists (index < n), nums[i] must be strictly greater than nums[i + k]
            if i + k < n:
                if nums[i] <= nums[i + k]:
                    is_good = False

            if is_good:
                total_sum += nums[i]

        return total_sum

