from itertools import permutations

class Solution:
    def totalNumbers(self, digits: List[int]) -> int:
        distinct_numbers = set()

        # Iterate through all permutations of length 3 from the digits array.
        # Since the length of digits is small (<= 10), the number of permutations is at most 720,
        # making this brute-force approach efficient.
        for p in permutations(digits, 3):
            # Check if the first digit is 0. Leading zeros are not allowed for 3-digit numbers.
            if p[0] == 0:
                continue

            # Check if the last digit is even to form an even number.
            if p[2] % 2 == 0:
                # Add the tuple to a set to ensure we count distinct numbers only.
                # Tuples are hashable and distinct based on their content.
                distinct_numbers.add(p)

        return len(distinct_numbers)
